import assert from 'node:assert/strict';
import { projectMonitoringState as project } from './archive/src/monitoring-state/project.mjs';
import { fixture, at, copy } from './archive/tests/monitoring-state/fixtures.mjs';
const results = [];
function probe(name, mutate, verify) {
  const f = fixture(); mutate(f); const out = project(f); verify(out);
  results.push({ name, status: out.location.status, freshness: out.location.freshness,
    reasons: out.location.reasons, lastKnown: out.location.lastKnown?.id ?? null });
}
probe('F1 source 300ms ahead', f => Object.assign(f.locations[0], {sourceAt:at(300), receivedAt:at(0)}),
  o => { assert.equal(o.location.status, 'unknown'); assert.ok(o.location.reasons.includes('source-after-server-receipt')); });
probe('F2 uncertainty30s point5s old', f => Object.assign(f.locations[0], {sourceAt:at(-5000), receivedAt:at(-4000), timeUncertaintyMs:30000}),
  o => { assert.equal(o.location.status, 'unknown'); assert.equal(o.location.ageMs.min, -25000); });
probe('F3a cadence3s uncertainty2s', f => {
  Object.assign(f.locations[0], {sourceAt:at(-4000), timeUncertaintyMs:2000});
  f.locations.push({...copy(f.locations[0]), id:'NEWER', sequence:2, sourceAt:at(-1000)});
}, o => { assert.equal(o.location.status, 'unknown'); assert.equal(o.location.lastKnown, null); });
probe('F3b old null uncertainty', f => f.locations.push({...copy(f.locations[0]), id:'OLDER', sequence:0, sourceAt:at(-60000), timeUncertaintyMs:null}),
  o => { assert.equal(o.location.status, 'unknown'); assert.equal(o.location.lastKnown, null); });
probe('F4 contact unknown driver permission', f => { f.availability.locationPermission='unknown'; },
  o => { assert.equal(o.location.status, 'unknown'); assert.equal(o.location.freshness, 'recent'); });
for (const state of ['pending','claimed','authorized','rejected','unknown','unavailable']) {
  const f=fixture(); f.notifications[0].state=state;
  assert.throws(()=>project(f), TypeError); results.push({name:`F5 backend job ${state}`, throws:'TypeError'});
}
for (const change of ['missing uncertainty','backend accuracy field']) {
  const f=fixture();
  if (change==='missing uncertainty') delete f.locations[0].timeUncertaintyMs;
  else {f.locations[0].accuracy=f.locations[0].accuracyMeters; delete f.locations[0].accuracyMeters;}
  assert.throws(()=>project(f), TypeError); results.push({name:`F5 ${change}`, throws:'TypeError'});
}
probe('F6 paused monotonic resume', f => { f.clock.wallMs+=60000; },
  o => { assert.equal(o.time.status, 'unknown'); assert.equal(o.location.status, 'unknown'); });
console.log(JSON.stringify({runtime:process.version, frozenSha:'e9df5cbfd5c2cfbb19698d46bb957b8561920e66', checks:results.length, results}, null, 2));
